-- =============================================================
-- data1.sql - Comprehensive test seed for HorseRace backend
-- Target: PostgreSQL with Hibernate-created schema
-- Usage: run after application schema is created, e.g. H2 console/RUNSCRIPT.
-- Fixed UUIDs make this script repeatable when tables are empty.
-- Password notes:
--   admin@horserace.local / Admin@123
--   owner*@horserace.local / Owner@123
--   jockey*@horserace.local / Jockey@123
--   referee*@horserace.local / Referee@123
--   spectator@horserace.local / Spec@123
-- =============================================================

-- Clean in FK-safe order so data can be reloaded.
DELETE FROM notifications WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM violations WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM race_results WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM referee_reports WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM registrations WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM races WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM tournaments WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM jockey_profiles WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM horses WHERE CAST(id AS TEXT) LIKE '10000000-%';
DELETE FROM users WHERE CAST(id AS TEXT) LIKE '10000000-%';

